@wangyunqian：分享下通过psci处理suspend_ops->enter的流程：

PSCI(power supply control interface), 是arm定义的一套处理cpu on/off/suspend等的协议，
比如Linux-kernel发送相应的cpu operation到和Trust-Zone（EL3 by smc）或Hypervirsor(EL2 by hvc)，再由TZ或Hyp做对应的操作：
比如： Linux-kernel 要offline、suspend一个cpu，Hypervisor只是把这个cpu给其它的OS使用。

回到suspend：
1， psci初始化：suspend_set_ops(&psci_suspend_ops);
	static const struct platform_suspend_ops psci_suspend_ops = {
		.enter          = psci_system_suspend_enter,
	};

2， psci_system_suspend：
	static int psci_system_suspend(unsigned long unused)
	{
		return invoke_psci_fn(PSCI_FN_NATIVE(1_0, SYSTEM_SUSPEND),
					  __pa_symbol(cpu_resume), 0, 0);
	}
	2.1，这里通过psci组装smc指令，跳转到TZ执行；
	2.2 cpu_resume是物理地址；
	2.3 Qualcom中TZ会和PMIC通信 power down此cpu；
	2.4 唤醒cpu重新power-up时，第一步执行cpu_resume；
		因为此时mmu还未打开，所以2.2必须传入cpu_resume的物理地址；
		cpu_resume中会打开mmu；

3， suspend_ops->enter，即	
	static int psci_system_suspend_enter(suspend_state_t state)
	{
		return cpu_suspend(0, psci_system_suspend);
	}
	
	arch/arm64/kernel/suspend.c
	int cpu_suspend(unsigned long arg, int (*fn)(unsigned long))
	{
		struct sleep_stack_data state;
		if (__cpu_suspend_enter(&state)) {
			ret = psci_system_suspend(arg);
		}
			
4， arch/arm64/kernel/sleep.S
	ENTRY(__cpu_suspend_enter)
	第一步保存当前lr到state中
	stp     x29, lr, [x0, #SLEEP_STACK_DATA_CALLEE_REGS]
	...
	mov     x0, #1		//这里返回1
	ret
	ENDPROC(__cpu_suspend_enter)

	ENTRY(cpu_resume)
			bl      el2_setup               // if in EL2 drop to EL1 cleanly
			bl      __cpu_setup
			/* enable the MMU early - so we can access sleep_save_stash by va */
			bl      __enable_mmu
			ldr     x8, =_cpu_resume
			br      x8
	ENDPROC(cpu_resume)
	
	ENTRY(_cpu_resume)
		...
        ldp     x29, lr, [x29]	//从之前的state中恢复lr
        mov     x0, #0			//返回值为0
        ret						//return到__cpu_suspend_enter下一行
	ENDPROC(_cpu_resume)

5， __cpu_suspend_enter/cpu_resume类似fork，有返回两次的效果：
	power-on-cpu时第一步会call cpu_resume；
	而cpu_resume返回时会返回到__cpu_suspend_enter的下一行。
    if (__cpu_suspend_enter(&state)) {
        /* 第一次返回1， 执行psci_system_suspend*/
        ret = psci_system_suspend(arg);
    } else {
		//由于cpu_resume返回值为0，那么resume后执行这一步：
        __cpu_suspend_exit();
    }
